create or replace function public.lp_mock_area_band(p_item jsonb)
returns integer language sql immutable set search_path='' as $$
 select case when p_item#>>'{itemSnapshot,adaptiveAreaVersion}' in ('areas-v1','areas-v2','areas-v3','areas-v4','areas-v5','areas-v6')
  and p_item#>>'{itemSnapshot,adaptiveAreaBand}'~'^[0-6]$'
  then (p_item#>>'{itemSnapshot,adaptiveAreaBand}')::integer else null end;
$$;

create or replace function public.lp_mock_placeholder_band_v11(p_domain text,p_ordinal integer)
returns integer language sql immutable set search_path='' as $$
 select case when p_domain='print' then case when p_ordinal>5 then 2 else 0 end
  else least(('{"sound_awareness":5,"phonics":6,"print":4,"vocabulary":5,"listening":6,"language":5,"reading":6,"writing":5}'::jsonb->>p_domain)::integer,case when p_ordinal<=3 then 0 else 1+(p_ordinal-4)/2 end) end;
$$;

create or replace function public.lp_mock_boundary_state_v11(p_rows jsonb)
returns jsonb language plpgsql immutable set search_path='' as $$
declare v_budgets jsonb:='{"sound_awareness":15,"phonics":17,"print":13,"vocabulary":15,"listening":17,"language":15,"reading":17,"writing":15}'::jsonb; v_maxima jsonb:='{"sound_awareness":5,"phonics":6,"print":4,"vocabulary":5,"listening":6,"language":5,"reading":6,"writing":5}'::jsonb;
 v_result jsonb:='{}'; v_domain text; v_max integer; v_row jsonb; v_item jsonb; v_band integer;
 v_next integer; v_answered integer; v_eligible integer; v_correct jsonb; v_wrong jsonb;
 v_letters text[]; v_letter text; v_reason text; v_boundary jsonb; v_non_independent integer; v_non_band integer; v_streak_band integer; v_correct_streak integer; v_wrong_streak integer; v_last_correct jsonb; v_last_wrong jsonb;
begin
 for v_domain in select value from jsonb_array_elements_text('["sound_awareness","phonics","print","vocabulary","listening","language","reading","writing"]'::jsonb) loop
  v_max:=(v_maxima->>v_domain)::integer; v_next:=0; v_answered:=0; v_eligible:=0;
  v_correct:=to_jsonb(array_fill(0,array[v_max+1])); v_wrong:=v_correct; v_last_correct:=v_correct; v_last_wrong:=v_correct; v_letters:='{}'; v_reason:=null; v_boundary:=null; v_non_independent:=0; v_non_band:=null; v_streak_band:=null; v_correct_streak:=0; v_wrong_streak:=0;
  for v_row in select value from jsonb_array_elements(coalesce(p_rows,'[]')) loop
   if v_row->>'responseStatus'='media_failed' then continue; end if;
   v_item:=coalesce(v_row->'itemSnapshot',v_row->'questionSnapshot',v_row);
   if v_item->>'domainId' is distinct from v_domain then continue; end if;
   v_band:=public.lp_mock_area_band(jsonb_build_object('itemSnapshot',v_item));
   if v_band is null or v_band<0 or v_band>v_max then continue; end if;
   v_answered:=v_answered+1;
   if v_domain='print' and v_band<=1 then
    v_letter:=coalesce(public.lp_literacy_print_letter_target(v_item),'question:'||coalesce(v_row->>'questionId',v_item->>'id',v_answered::text));
    if not v_letter=any(v_letters) then v_letters:=array_append(v_letters,v_letter); end if;
   end if;
   if (v_row ? 'classification' and v_row->>'classification'<>'independent') or not public.lp_literacy_response_eligible(v_row) then
    v_non_independent:=case when v_non_band=v_band then v_non_independent+1 else 1 end; v_non_band:=v_band; v_correct_streak:=0; v_wrong_streak:=0; v_next:=v_band; continue;
   end if;
   v_non_independent:=0; v_non_band:=null;
   v_eligible:=v_eligible+1;
   if v_streak_band is distinct from v_band then v_correct_streak:=0; v_wrong_streak:=0; end if;
   v_streak_band:=v_band; v_next:=v_band;
   if (v_row->>'isCorrect')::boolean then
    v_last_correct:=jsonb_set(v_last_correct,array[v_band::text],to_jsonb(v_answered)); v_correct:=jsonb_set(v_correct,array[v_band::text],to_jsonb((v_correct->>v_band)::integer+1)); v_correct_streak:=v_correct_streak+1; v_wrong_streak:=0;
    if v_correct_streak>=(case when v_band=0 then 3 else 2 end) then v_next:=least(v_max,v_band+1); end if;
   else
    v_last_wrong:=jsonb_set(v_last_wrong,array[v_band::text],to_jsonb(v_answered)); v_wrong:=jsonb_set(v_wrong,array[v_band::text],to_jsonb((v_wrong->>v_band)::integer+1)); v_wrong_streak:=v_wrong_streak+1; v_correct_streak:=0;
    if v_wrong_streak>=2 then v_next:=greatest(0,v_band-1); end if;
   end if;
  end loop;
  if (v_correct->>v_max)::integer>=2 then
   v_reason:='ceiling_confirmed'; v_boundary:=jsonb_build_object('lowerBand',v_max,'upperBand',null);
  elsif (v_wrong->>0)::integer>=2 then
   v_reason:='floor_confirmed'; v_boundary:=jsonb_build_object('lowerBand',null,'upperBand',0);
  else
   for v_band in reverse v_max-1..0 loop
    if (v_correct->>v_band)::integer>=(case when v_band=0 then 3 else 2 end) and (v_wrong->>(v_band+1))::integer>=2 and (v_last_correct->>v_band)::integer>(v_last_wrong->>(v_band+1))::integer then
     v_reason:='adjacent_boundary'; v_boundary:=jsonb_build_object('lowerBand',v_band,'upperBand',v_band+1); exit;
    end if;
   end loop;
  end if;
  if v_reason is null and v_non_independent>=2 then v_reason:='independent_followup_needed'; end if;
  if v_reason is null and v_domain='print' and v_next<=1 and cardinality(v_letters)>=5 then v_reason:='letter_limit'; end if;
  if v_reason is null and v_answered>=(v_budgets->>v_domain)::integer then v_reason:='budget_limit'; end if;
  v_result:=v_result||jsonb_build_object(v_domain,jsonb_build_object('domainId',v_domain,'nextBand',v_next,'answered',v_answered,'eligible',v_eligible,
   'lastCorrectByBand',v_last_correct,'lastIncorrectByBand',v_last_wrong,'streakBand',v_streak_band,'correctStreak',v_correct_streak,'incorrectStreak',v_wrong_streak,'correctByBand',v_correct,'incorrectByBand',v_wrong,'lowerLetterTargets',to_jsonb(v_letters),'nonIndependentStreak',v_non_independent,'nonIndependentBand',v_non_band,'stopReason',v_reason,'boundary',v_boundary,'complete',v_reason is not null));
 end loop;
 return v_result;
end; $$;

create or replace function public.lp_mock_boundary_schedule_with_state_v11(p_rows jsonb,v_states jsonb)
returns jsonb language plpgsql immutable set search_path='' as $$
declare v_budgets jsonb:='{"sound_awareness":15,"phonics":17,"print":13,"vocabulary":15,"listening":17,"language":15,"reading":17,"writing":15}'::jsonb;
 v_order jsonb:='["sound_awareness","phonics","print","vocabulary","listening","language","reading","writing"]'::jsonb; v_seen jsonb:='{}'; v_schedule jsonb:='[]'; v_row jsonb; v_domain text; v_round integer; v_slot integer; v_ordinal integer;
begin
 for v_row in select value from jsonb_array_elements(coalesce(p_rows,'[]')) loop
  if v_row->>'responseStatus'='media_failed' then continue; end if;
  v_domain:=coalesce(v_row#>>'{itemSnapshot,domainId}',v_row#>>'{questionSnapshot,domainId}',v_row->>'domainId');
  if v_domain is null or not v_budgets ? v_domain then raise exception 'Invalid adaptive boundary history'; end if;
  v_schedule:=v_schedule||jsonb_build_array(v_domain);
 end loop;
 for v_domain in select value from jsonb_array_elements_text(v_order) loop
  if (v_states#>>array[v_domain,'answered'])::integer>(v_budgets->>v_domain)::integer then raise exception 'Invalid adaptive boundary history'; end if;
 end loop;
 if jsonb_array_length(v_schedule)>124 then raise exception 'Invalid adaptive boundary history'; end if;
 for v_round in 0..8 loop
  for v_domain in select value from jsonb_array_elements_text(v_order) loop
   for v_slot in 1..2 loop
    v_ordinal:=v_round*2+v_slot;
    if v_ordinal<=(v_budgets->>v_domain)::integer and v_ordinal>(v_states#>>array[v_domain,'answered'])::integer
     and not (v_states#>>array[v_domain,'complete'])::boolean then v_schedule:=v_schedule||jsonb_build_array(v_domain); end if;
   end loop;
  end loop;
 end loop;
 return v_schedule;
end; $$;

create or replace function public.lp_mock_boundary_state_for_version(p_rows jsonb,p_version text)
returns jsonb language sql immutable set search_path='' as $$
 select case when p_version='literacy-mock-v11' then public.lp_mock_boundary_state_v11(p_rows) else public.lp_mock_boundary_state_v9(p_rows) end;
$$;
create or replace function public.lp_mock_boundary_schedule_for_version(p_rows jsonb,p_states jsonb,p_version text)
returns jsonb language sql immutable set search_path='' as $$
 select case when p_version='literacy-mock-v11' then public.lp_mock_boundary_schedule_with_state_v11(p_rows,p_states) else public.lp_mock_boundary_schedule_with_state_v9(p_rows,p_states) end;
$$;

create or replace function public.lp_guard_literacy_mock_run() returns trigger language plpgsql set search_path='' as $$
declare v_count integer:=jsonb_array_length(old.responses);
begin
  if not exists(select 1 from public.student_focus_sessions where id=old.session_id and content_version='literacy-mock-v11') and jsonb_array_length(new.responses)>67 then raise exception 'Legacy mock response bound'; end if;
  if not exists(select 1 from public.student_focus_sessions where id=old.session_id and content_version in ('literacy-mock-v9','literacy-mock-v10','literacy-mock-v11'))
   and jsonb_array_length(new.responses)>50 then raise exception 'Legacy mock response limit'; end if;
  if new.session_id<>old.session_id or new.student_id<>old.student_id
    or jsonb_array_length(new.responses)<v_count
    or exists(select 1 from jsonb_array_elements(old.responses) with ordinality r(response,position)
      where response is distinct from new.responses->(position::integer-1))
    or jsonb_array_length(new.media_failures)<jsonb_array_length(old.media_failures)
    or exists(select 1 from jsonb_array_elements(old.media_failures) with ordinality f(failure,position)
      where failure is distinct from new.media_failures->(position::integer-1))
    or new.plan_history<>old.plan_history
    or (old.status='completed' and (new.plan<>old.plan or new.responses<>old.responses or new.media_failures<>old.media_failures or new.status<>old.status)) then
    raise exception 'Mock first-response evidence is immutable'; end if;
  if new.plan<>old.plan then
    if new.plan->'seed'<>old.plan->'seed' or (case when exists(select 1 from public.student_focus_sessions where id=old.session_id and content_version in ('literacy-mock-v9','literacy-mock-v10','literacy-mock-v11'))
       then jsonb_array_length(new.plan->'itemIds') not between v_count and (select item_count from public.literacy_mock_sessions where session_id=old.session_id)
       else jsonb_array_length(new.plan->'itemIds')<>jsonb_array_length(old.plan->'itemIds') end)
      or exists(select 1 from jsonb_array_elements(old.plan->'itemIds') with ordinality p(id,position)
        where position<=v_count and id is distinct from new.plan->'itemIds'->(position::integer-1)) then
      raise exception 'Mock answered plan prefix is immutable'; end if;
    new.plan_history:=old.plan_history||jsonb_build_array(jsonb_build_object('previousPlan',old.plan,'afterResponses',v_count,'changedAt',clock_timestamp()));
  end if;
  return new;
end; $$;

create or replace function public.lp_progress_config_valid(p_config jsonb,p_version text)
returns boolean language plpgsql stable security definer set search_path='' as $$
begin
  if p_version in ('literacy-mock-v1','literacy-mock-v2','literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11')
    and p_config=jsonb_build_object('plan_kind','mock','track_id','all','bank_version',p_version) then return true; end if;
  return public.lp_progress_config_valid_before_mock(p_config,p_version);
end; $$;

create or replace function public.lp_literacy_mock_assignment(p_student_id uuid,p_session_id uuid)
returns boolean language sql stable security definer set search_path='' as $$
  select exists(select 1 from public.student_focus_sessions f
    join public.student_focus_session_members m on m.session_id=f.id
    join public.students s on s.id=m.student_id
    join public.literacy_mock_sessions w on w.session_id=f.id
    where f.id=p_session_id and m.student_id=p_student_id and s.archived_at is null
      and s.teacher_id=f.teacher_id and s.class_id=f.class_id and f.target='progress_check'
      and f.content_version in ('literacy-mock-v1','literacy-mock-v2','literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11')
      and m.resolved_config=jsonb_build_object('plan_kind','mock','track_id','all','bank_version',f.content_version));
$$;

create or replace function public.lp_prepare_literacy_mock_focus(p_class_id uuid,p_student_ids uuid[],p_whole_class boolean,p_version text)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare v_ids uuid[]; v_id uuid; v_actor uuid:=auth.uid(); v_now timestamptz:=clock_timestamp();
begin
  perform public.assert_current_actor_teacher_access();
  if p_class_id is null or p_whole_class is null or p_version is null
    or p_version not in ('literacy-mock-v1','literacy-mock-v2','literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') then
    return jsonb_build_object('ok',false,'error','invalid_payload'); end if;
  perform 1 from public.classes where id=p_class_id and teacher_id=v_actor for update;
  if not found then return jsonb_build_object('ok',false,'error','class_not_found'); end if;
  if p_whole_class then
    if coalesce(cardinality(p_student_ids),0)<>0 then
      return jsonb_build_object('ok',false,'error','whole_class_ids_must_be_empty'); end if;
    select array_agg(id order by id) into v_ids from public.students
      where class_id=p_class_id and teacher_id=v_actor and archived_at is null;
    if coalesce(cardinality(v_ids),0)=0 then return jsonb_build_object('ok',false,'error','class_has_no_active_students'); end if;
  else
    v_ids:=p_student_ids;
  end if;
  if coalesce(cardinality(v_ids),0) not between 1 and 200
    or (select count(distinct id) from unnest(v_ids) id)<>cardinality(v_ids) then
    return jsonb_build_object('ok',false,'error','invalid_payload'); end if;
  perform 1 from public.students where id=any(v_ids) order by id for update;
  if exists(select 1 from unnest(v_ids) requested(id) left join public.students s
    on s.id=requested.id and s.class_id=p_class_id and s.teacher_id=v_actor and s.archived_at is null
    where s.id is null) then return jsonb_build_object('ok',false,'error','student_not_in_class'); end if;
  insert into public.student_focus_sessions(teacher_id,class_id,target,content_version,selection_scope,status,started_at,expires_at)
    values(v_actor,p_class_id,'progress_check',p_version,case when p_whole_class then 'whole_class' else 'selected_students' end,
      'prepared',v_now,v_now+interval '2 hours') returning id into v_id;
  insert into public.student_focus_session_members(session_id,student_id,resolved_config,active)
    select v_id,id,jsonb_build_object('plan_kind','mock','track_id','all','bank_version',p_version),false from unnest(v_ids) id;
  return jsonb_build_object('ok',true,'session',jsonb_build_object('id',v_id));
end; $$;

create or replace function public.lp_mock_state_before_delivery(p_session_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare v_focus public.student_focus_sessions; v_mock public.literacy_mock_sessions; v_now timestamptz:=clock_timestamp();
begin
  select * into v_focus from public.student_focus_sessions where id=p_session_id for update;
  select * into v_mock from public.literacy_mock_sessions where session_id=p_session_id for update;
  if v_mock.session_id is null then return null; end if;
  v_now:=clock_timestamp();
  if v_mock.state<>'completed' and (v_focus.status='ended' or v_focus.expires_at<=v_now
    or (v_mock.state='running' and v_mock.deadline_at<=v_now and v_mock.window_mode='timed_sample')) then
    update public.literacy_mock_sessions set state='completed',revision=revision+1,remaining_seconds=0,deadline_at=null,
      ended_at=v_now,end_reason=case when v_focus.status='ended' then 'teacher_closed'
        when v_focus.expires_at<=v_now then 'session_expired' else 'time_finished' end,updated_at=v_now
      where session_id=p_session_id returning * into v_mock;
    update public.literacy_mock_runs set status='completed',completed_at=coalesce(completed_at,v_now),updated_at=v_now
      where session_id=p_session_id and status<>'completed';
    update public.student_focus_session_members set status='completed',completed_at=coalesce(completed_at,v_now),updated_at=v_now
      where session_id=p_session_id;
    update public.student_focus_session_members set active=false where session_id=p_session_id;
    update public.student_focus_sessions set status='ended',ended_at=coalesce(ended_at,v_now),updated_at=v_now where id=p_session_id;
  elsif v_mock.state='running' and v_mock.deadline_at<=v_now then
    update public.literacy_mock_sessions set state='paused',revision=revision+1,remaining_seconds=duration_seconds,
      deadline_at=null,pause_reason='window_elapsed',updated_at=v_now where session_id=p_session_id returning * into v_mock;
  end if;
  return (to_jsonb(v_mock)-'session_id')||jsonb_build_object('server_now',v_now,'content_version',v_focus.content_version,
    'capabilities',jsonb_build_object('contentQuarantineRepair',true,'presentationReceipts',v_focus.content_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11'),'supportResolution',v_focus.content_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11'),
      'entryChecks',v_focus.content_version in ('literacy-mock-v3','literacy-mock-v4'),'freshChecks',v_focus.content_version in ('literacy-mock-v3','literacy-mock-v4'),'windowModes',v_focus.content_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11')),
    'remaining_seconds',case when v_mock.state='running' then greatest(0,ceil(extract(epoch from(v_mock.deadline_at-v_now)))::integer)
      else least(v_mock.remaining_seconds,greatest(0,ceil(extract(epoch from(v_focus.expires_at-v_now)))::integer)) end);
end; $$;

create or replace function public.lp_mock_run_before_delivery(p_session_id uuid,p_student_id uuid)
returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('schemaVersion',case when f.content_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') then 2 else 1 end,
  'contentVersion',f.content_version,'assignmentId',r.session_id,'studentId',r.student_id,'revision',r.revision,
  'windowMode',w.window_mode,'durationSeconds',w.duration_seconds,
  'timeExtensionCount',(select count(*) from public.literacy_mock_controls c where c.session_id=r.session_id and c.action='add_time'),
  'plan',r.plan,'planHistory',r.plan_history,'responses',case when f.content_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') then
   coalesce((select jsonb_agg(public.lp_literacy_mock_effective_response(p_session_id,p_student_id,response) order by position)
    from jsonb_array_elements(r.responses) with ordinality e(response,position)),'[]'::jsonb) else coalesce((select jsonb_agg(public.lp_literacy_content_response(response) order by position)
    from jsonb_array_elements(r.responses) with ordinality e(response,position)),'[]'::jsonb) end,
  'status',r.status,'mediaFailures',r.media_failures,'completedAt',r.completed_at,'updatedAt',r.updated_at,
  'presentationTracking',f.content_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11'),
  'eventRevision',coalesce((select max(event_id) from public.literacy_mock_events where session_id=p_session_id and student_id=p_student_id),0),
  'presentations',coalesce((select jsonb_agg(e.payload||jsonb_build_object('serverReceivedAt',e.created_at) order by e.event_id)
   from public.literacy_mock_events e where e.session_id=p_session_id and e.student_id=p_student_id and e.event_type='presented'),'[]'::jsonb),
  'helpRequests',coalesce((select jsonb_agg(public.lp_literacy_mock_help(p_session_id,p_student_id,q.question_id)
   ||jsonb_build_object('itemSnapshot',(select payload->'itemSnapshot' from public.literacy_mock_events where session_id=p_session_id and student_id=p_student_id and question_id=q.question_id and event_type='presented' order by event_id limit 1)))
   from (select distinct question_id from public.literacy_mock_events where session_id=p_session_id and student_id=p_student_id
    and event_type in ('help_requested','help_cancelled','support_resolved')) q),'[]'::jsonb),
  'unsampledItemIds',coalesce((select jsonb_agg(item_id order by position)
   from jsonb_array_elements(r.plan->'itemIds') with ordinality p(item_id,position)
   where position>jsonb_array_length(r.responses)),'[]'::jsonb))
 from public.literacy_mock_runs r join public.student_focus_sessions f on f.id=r.session_id
 join public.literacy_mock_sessions w on w.session_id=r.session_id
 where r.session_id=p_session_id and r.student_id=p_student_id;
$$;

create or replace function public.lp_mock_support_before_delivery(p_session_id uuid,p_student_id uuid,p_question_id text,p_assistance text,p_request_id text)
returns json language plpgsql volatile security definer set search_path='' as $$
declare v_mock jsonb; v_run public.literacy_mock_runs; v_event public.literacy_mock_events; v_actor text;
begin
 perform public.assert_current_actor_teacher_access();
 perform 1 from public.student_focus_sessions where id=p_session_id and teacher_id=auth.uid() for update;
 if not found or not public.lp_literacy_mock_assignment(p_student_id,p_session_id) then return json_build_object('ok',false,'error','session_not_found'); end if;
 if p_assistance is null or p_assistance not in ('none','access','answer') or coalesce(char_length(p_request_id),0) not between 1 and 160 then
  return json_build_object('ok',false,'error','invalid_support'); end if;
 v_mock:=public.lp_literacy_mock_state(p_session_id);
 if v_mock->>'content_version' not in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') then return json_build_object('ok',false,'error','unsupported_event_version'); end if;
 select * into v_run from public.literacy_mock_runs where session_id=p_session_id and student_id=p_student_id for update;
 if not found then return json_build_object('ok',false,'error','run_not_found'); end if;
 v_actor:='teacher:'||auth.uid()::text;
 select * into v_event from public.literacy_mock_events where session_id=p_session_id and student_id=p_student_id and actor_key=v_actor and request_id=p_request_id;
 if found then
  if v_event.question_id<>p_question_id or v_event.payload->>'assistance'<>p_assistance then return json_build_object('ok',false,'error','request_conflict'); end if;
  return json_build_object('ok',true,'duplicate',true,'mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,p_student_id));
 end if;
 if not exists(select 1 from public.literacy_mock_events where session_id=p_session_id and student_id=p_student_id and question_id=p_question_id and event_type='presented') then
  return json_build_object('ok',false,'error','presentation_required'); end if;
 insert into public.literacy_mock_events(session_id,student_id,question_id,actor_key,request_id,event_type,payload)
  values(p_session_id,p_student_id,p_question_id,v_actor,p_request_id,'support_resolved',jsonb_build_object('assistance',p_assistance));
 return json_build_object('ok',true,'mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,p_student_id));
end; $$;

create or replace function public.lp_literacy_mock_state(p_session_id uuid)
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare v_mock jsonb; v_pending integer; v_received integer;
begin
 v_mock:=public.lp_mock_state_before_delivery(p_session_id);
 if v_mock is null then return null; end if;
 select count(*) filter(where r.offline_lease_id is not null and r.status<>'completed'
   and r.collection_ack_id is distinct from v_mock->>'collection_id'),
  count(*) filter(where r.offline_lease_id is not null and (r.status='completed' or r.collection_ack_id=v_mock->>'collection_id'))
 into v_pending,v_received from public.literacy_mock_runs r where r.session_id=p_session_id;
 return v_mock||jsonb_build_object('capabilities',coalesce(v_mock->'capabilities','{}'::jsonb)||
  jsonb_build_object('offlineDelivery',v_mock->>'content_version' in ('literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') and v_mock->>'window_mode'='untimed'),
  'collection_pending_count',v_pending,'collection_received_count',v_received);
end; $$;

create or replace function public.teacher_control_literacy_mock_session(p_session_id uuid,p_action text,p_expected_revision integer,p_request_id text)
returns json language plpgsql volatile security definer set search_path='' as $$
declare v_focus public.student_focus_sessions; v_mock jsonb; v_saved public.literacy_mock_controls; v_collect boolean; v_result json;
begin
 perform public.assert_current_actor_teacher_access();
 select * into v_focus from public.student_focus_sessions where id=p_session_id and teacher_id=auth.uid() for update;
 if not found then return json_build_object('ok',false,'error','session_not_found'); end if;
 v_collect:=p_action='collect' or (p_action='finish' and exists(select 1 from public.literacy_mock_runs r
  where r.session_id=p_session_id and r.offline_lease_id is not null and r.status<>'completed'));
 if p_action not in ('collect','live_on','live_off') and not v_collect then
  if exists(select 1 from public.literacy_mock_sessions where session_id=p_session_id and window_mode='untimed') then
   update public.literacy_mock_sessions set window_mode='pause_at_window_end',
    deadline_at=case when state='running' then clock_timestamp()+interval '1 hour' else null end where session_id=p_session_id;
   v_result:=public.lp_mock_control_before_delivery(p_session_id,p_action,p_expected_revision,p_request_id);
   update public.literacy_mock_sessions set window_mode='untimed',deadline_at=null where session_id=p_session_id;
   if v_result->>'ok'='true' then return (public.teacher_get_student_focus_session(p_session_id)::jsonb||jsonb_build_object('duplicate',coalesce((v_result->>'duplicate')::boolean,false)))::json; end if;
   return v_result;
  end if;
  return public.lp_mock_control_before_delivery(p_session_id,p_action,p_expected_revision,p_request_id);
 end if;
 if p_expected_revision is null or p_expected_revision<0 or coalesce(char_length(p_request_id),0) not between 1 and 160 then
  return json_build_object('ok',false,'error','invalid_control'); end if;
 v_mock:=public.lp_literacy_mock_state(p_session_id);
 if v_mock is null then return json_build_object('ok',false,'error','mock_not_found'); end if;
 select * into v_saved from public.literacy_mock_controls where session_id=p_session_id and request_id=p_request_id;
 if found then
  if v_saved.action<>p_action or v_saved.expected_revision<>p_expected_revision then return json_build_object('ok',false,'error','request_conflict'); end if;
  perform public.lp_finish_mock_collection(p_session_id);
  return (public.teacher_get_student_focus_session(p_session_id)::jsonb||jsonb_build_object('duplicate',true))::json;
 end if;
 if v_mock->>'content_version' not in ('literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') or v_mock->>'window_mode'<>'untimed' then return json_build_object('ok',false,'error','unsupported_delivery_mode'); end if;
 if v_mock->>'state'='completed' then return json_build_object('ok',false,'error','assessment_finished','mock',v_mock); end if;
 if (v_mock->>'revision')::integer<>p_expected_revision then return json_build_object('ok',false,'error','stale_revision','mock',v_mock); end if;
 if p_expected_revision>=500 then return json_build_object('ok',false,'error','control_limit'); end if;
 if v_mock->>'collection_id' is not null then return json_build_object('ok',false,'error','collection_in_progress','mock',v_mock); end if;
 update public.literacy_mock_sessions set revision=revision+1,
  delivery_mode=case when p_action='live_on' then 'live' when p_action='live_off' then 'collect' else delivery_mode end,
  collection_id=case when v_collect then p_request_id else collection_id end,
  collection_requested_at=case when v_collect then clock_timestamp() else collection_requested_at end,updated_at=clock_timestamp()
  where session_id=p_session_id;
 insert into public.literacy_mock_controls(session_id,request_id,action,expected_revision,result_revision)
  values(p_session_id,p_request_id,p_action,p_expected_revision,p_expected_revision+1);
 if v_collect then perform public.lp_finish_mock_collection(p_session_id); end if;
 return public.teacher_get_student_focus_session(p_session_id);
end; $$;

create or replace function public.student_sync_literacy_mock_batch(p_token text,p_session_id uuid,p_batch_id text,p_lease_id uuid,
 p_requests jsonb,p_collection_id text default null)
returns json language plpgsql volatile security definer set search_path='' as $$
declare v_student public.students; v_focus public.student_focus_sessions; v_mock jsonb; v_run public.literacy_mock_runs;
 v_saved public.literacy_mock_delivery_receipts; v_hash text; v_request jsonb; v_result jsonb; v_receipt jsonb;
 v_ack jsonb:='[]'; v_error text; v_state text; v_deadline timestamptz; v_projection text:=current_setting('literacy_mock.batch_receipt_only',true);
begin
 v_student:=public.student_from_token(p_token);
 if v_student.id is null then return json_build_object('ok',false,'error','invalid_session'); end if;
 perform 1 from public.students where id=v_student.id for share;
 if not public.lp_literacy_mock_assignment(v_student.id,p_session_id) then return json_build_object('ok',false,'error','assignment_not_found'); end if;
 if coalesce(char_length(p_batch_id),0) not between 1 and 160 or jsonb_typeof(p_requests) is distinct from 'array'
  or jsonb_array_length(p_requests)>512 or octet_length(p_requests::text)>3000000 then return json_build_object('ok',false,'error','invalid_batch'); end if;
 select * into v_focus from public.student_focus_sessions where id=p_session_id for update;
 select * into v_run from public.literacy_mock_runs where session_id=p_session_id and student_id=v_student.id for update;
 if v_run.session_id is null then return json_build_object('ok',false,'error','run_not_registered'); end if;
 v_hash:=md5(jsonb_build_object('lease',p_lease_id,'requests',p_requests,'collection',p_collection_id)::text);
 select * into v_saved from public.literacy_mock_delivery_receipts where session_id=p_session_id and student_id=v_student.id and batch_id=p_batch_id;
 if found then
  if v_saved.payload_hash<>v_hash then return json_build_object('ok',false,'error','request_conflict'); end if;
  return (v_saved.receipt||jsonb_build_object('duplicate',true))::json;
 end if;
 v_mock:=public.lp_literacy_mock_state(p_session_id);
 if v_mock->>'content_version' not in ('literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') or v_mock->>'window_mode'<>'untimed' then return json_build_object('ok',false,'error','unsupported_delivery_mode'); end if;
 if v_focus.status<>'active' or v_focus.expires_at<=clock_timestamp() or v_mock->>'state'='completed' then return json_build_object('ok',false,'error','assessment_finished'); end if;
 if p_lease_id is null then
  if jsonb_array_length(p_requests)<>0 or p_collection_id is not null or v_mock->>'state'<>'running' or v_mock->>'collection_id' is not null
   or v_run.status='completed' then return json_build_object('ok',false,'error','invalid_device_bootstrap'); end if;
  if v_run.offline_lease_id is null then
   -- An untimed device test gets a receiving window bounded to the school day.
   update public.student_focus_sessions set device_receiving_window=true,expires_at=greatest(expires_at,started_at+interval '12 hours') where id=p_session_id returning * into v_focus;
   update public.literacy_mock_runs set offline_lease_id=gen_random_uuid(),offline_lease_expires_at=v_focus.expires_at
    where session_id=p_session_id and student_id=v_student.id returning * into v_run;
  end if;
 else
  if v_run.offline_lease_id is distinct from p_lease_id or v_run.offline_lease_expires_at<=clock_timestamp() then
   return json_build_object('ok',false,'error','invalid_device_lease'); end if;
 end if;
 if p_collection_id is not null and p_collection_id is distinct from v_mock->>'collection_id' then return json_build_object('ok',false,'error','stale_collection'); end if;
 v_state:=v_mock->>'state';
 select deadline_at into v_deadline from public.literacy_mock_sessions where session_id=p_session_id;
 begin
  -- A pause stops new local work when received. Previously authorized queued
  -- answers can drain while paused; the externally visible state is restored
  -- within this same transaction, before a receipt can be returned.
  if v_state='paused' then update public.literacy_mock_sessions set state='running',deadline_at=null where session_id=p_session_id; end if;
  perform set_config('literacy_mock.batch_receipt_only','on',true);
  for v_request in select value from jsonb_array_elements(p_requests) loop
   if jsonb_typeof(v_request)<>'object' or coalesce(char_length(v_request->>'requestId'),0) not between 1 and 160 then
    v_error:='invalid_batch_request'; raise exception 'batch_rejected'; end if;
   if v_request->>'type'='event' then
    v_result:=public.student_record_literacy_mock_event(p_token,p_session_id,v_request->>'questionId',v_request->>'event',v_request->>'requestId')::jsonb;
   else
    if v_request->>'expectedRevision' !~ '^[0-9]{1,9}$' then v_error:='invalid_batch_revision'; raise exception 'batch_rejected'; end if;
    v_result:=public.student_save_literacy_mock_run(p_token,p_session_id,v_request->>'requestId',(v_request->>'expectedRevision')::integer,
     nullif(v_request->'plan','null'::jsonb),nullif(v_request->'response','null'::jsonb))::jsonb;
   end if;
   if v_result->>'ok' is distinct from 'true' then v_error:=coalesce(v_result->>'error','batch_rejected'); raise exception 'batch_rejected'; end if;
   v_ack:=v_ack||jsonb_build_array(v_request->>'requestId');
  end loop;
  perform set_config('literacy_mock.batch_receipt_only',coalesce(v_projection,''),true);
  if v_state='paused' then update public.literacy_mock_sessions set state='paused',deadline_at=v_deadline where session_id=p_session_id; end if;
  if p_collection_id is not null then
   update public.literacy_mock_runs set collection_ack_id=p_collection_id,collection_ack_at=clock_timestamp()
    where session_id=p_session_id and student_id=v_student.id;
  end if;
  perform public.lp_finish_mock_collection(p_session_id);
  v_receipt:=jsonb_build_object('ok',true,'mock',public.lp_literacy_mock_state(p_session_id),
   'run',public.lp_literacy_mock_run_json(p_session_id,v_student.id),'acknowledged',v_ack,'batchId',p_batch_id);
  insert into public.literacy_mock_delivery_receipts(session_id,student_id,batch_id,payload_hash,receipt)
   values(p_session_id,v_student.id,p_batch_id,v_hash,v_receipt);
  return v_receipt::json;
 exception when others then
  perform set_config('literacy_mock.batch_receipt_only',coalesce(v_projection,''),true);
  return json_build_object('ok',false,'error',coalesce(v_error,'batch_rejected'));
 end;
end; $$;

create or replace function public.student_save_literacy_mock_run(p_token text,p_session_id uuid,p_request_id text,
  p_expected_revision integer,p_plan jsonb default null,p_response jsonb default null)
returns json language plpgsql volatile security definer set search_path='' as $$
declare
  v_student public.students; v_mock jsonb; v_run public.literacy_mock_runs; v_request public.literacy_mock_run_requests;
  v_payload jsonb; v_plan jsonb; v_item jsonb; v_old_item jsonb; v_answer jsonb; v_previous jsonb; v_failure jsonb; v_failed_paths jsonb;
  v_version text; v_familiarity jsonb; v_prior jsonb; v_presentation jsonb; v_id text; v_index integer; v_count integer; v_expected_level integer; v_area_error text; v_valid boolean; v_now timestamptz;
begin
  v_student:=public.student_from_token(p_token);
  if v_student.id is null then return json_build_object('ok',false,'error','invalid_session'); end if;
  perform 1 from public.students where id=v_student.id for share;
  if not public.lp_literacy_mock_assignment(v_student.id,p_session_id) then
    return json_build_object('ok',false,'error','assignment_not_found'); end if;
  if coalesce(char_length(p_request_id),0) not between 1 and 160 or p_expected_revision is null or p_expected_revision<0
    or (p_plan is null and p_response is null) or octet_length(coalesce(p_plan,'{}')::text)>20000
    or octet_length(coalesce(p_response,'{}')::text)>32000 then
    return json_build_object('ok',false,'error','invalid_payload'); end if;
  v_mock:=public.lp_literacy_mock_state(p_session_id);
  select content_version into v_version from public.student_focus_sessions where id=p_session_id;
  v_payload:=jsonb_build_object('expectedRevision',p_expected_revision,'plan',p_plan,'response',p_response);
  select * into v_request from public.literacy_mock_run_requests where session_id=p_session_id and student_id=v_student.id and request_id=p_request_id;
  if found then
    if v_request.request_payload<>v_payload then return json_build_object('ok',false,'error','request_conflict'); end if;
    return json_build_object('ok',true,'duplicate',true,'mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,v_student.id));
  end if;
  if v_mock->>'state'='completed' or not exists(select 1 from public.student_focus_sessions f
    join public.student_focus_session_members m on m.session_id=f.id where f.id=p_session_id
      and f.status='active' and f.expires_at>clock_timestamp() and m.student_id=v_student.id and m.active) then
    return json_build_object('ok',false,'error','assessment_finished','mock',v_mock); end if;
  select * into v_run from public.literacy_mock_runs where session_id=p_session_id and student_id=v_student.id for update;
  if coalesce(v_run.revision,0)<>p_expected_revision then
    return json_build_object('ok',false,'error','stale_revision','mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,v_student.id)); end if;
  if v_run.status='completed' then return json_build_object('ok',false,'error','run_completed'); end if;
  if p_response is not null and v_mock->>'state'<>'running' then
    return json_build_object('ok',false,'error','assessment_not_running','mock',v_mock); end if;
  v_count:=coalesce(jsonb_array_length(v_run.responses),0);
  if v_run.revision>=256 or (p_plan is not null and p_plan is distinct from v_run.plan and coalesce(jsonb_array_length(v_run.plan_history),0)>=128)
    or (p_response->>'responseStatus'='media_failed' and coalesce(jsonb_array_length(v_run.media_failures),0)>=128) then
    return json_build_object('ok',false,'error','run_mutation_limit'); end if;
  v_plan:=coalesce(v_run.plan,p_plan);
  if p_plan is not null then
    if jsonb_typeof(p_plan) is distinct from 'object' or jsonb_typeof(p_plan->'itemIds') is distinct from 'array'
      or jsonb_typeof(p_plan->'seed') is distinct from 'string' or char_length(p_plan->>'seed') not between 1 and 160
      or exists(select 1 from jsonb_object_keys(p_plan) k where k not in ('itemIds','seed'))
      or (case when v_version in ('literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') then jsonb_array_length(p_plan->'itemIds') not between v_count and (v_mock->>'item_count')::integer else jsonb_array_length(p_plan->'itemIds')<>(v_mock->>'item_count')::integer end)
      or (select count(distinct value) from jsonb_array_elements(p_plan->'itemIds'))<>jsonb_array_length(p_plan->'itemIds') then
      return json_build_object('ok',false,'error','invalid_plan'); end if;
    if v_run.session_id is not null and (p_plan->'seed'<>v_run.plan->'seed'
      or (v_mock->>'state'<>'running' and p_plan<>v_run.plan)) then
      return json_build_object('ok',false,'error','plan_conflict'); end if;
    for v_id,v_index in select value,ordinality::integer from jsonb_array_elements_text(p_plan->'itemIds') with ordinality loop
      select item into v_item from public.literacy_mock_items where id=v_id and content_version=v_version;
      if v_item is null then return json_build_object('ok',false,'error','unknown_item'); end if;
      if v_index>v_count and public.lp_literacy_item_quarantined(v_item) then
        return json_build_object('ok',false,'error','content_item_withdrawn'); end if;
      if v_index>v_count and public.lp_literacy_mock_item_blocked(v_item,v_run.media_failures) then
        return json_build_object('ok',false,'error','blocked_media_item'); end if;
      -- Canonical identity/conditions of an unchanged slot are immutable. Its
      -- live quarantine and media checks above still run on every update.
      if v_version in ('literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') and v_run.session_id is not null
        and v_id=v_run.plan->'itemIds'->>(v_index-1) then continue; end if;
      if v_item#>>'{itemSnapshot,tutorialOnly}'='true' or exists (
        select 1 from public.literacy_mock_items tutorial where tutorial.content_version=v_version
          and tutorial.item#>>'{itemSnapshot,tutorialOnly}'='true'
          and nullif(v_item#>>'{itemSnapshot,stimulusKey}','')=tutorial.item#>>'{itemSnapshot,stimulusKey}') then
        return json_build_object('ok',false,'error','tutorial_item_not_scored'); end if;
      if v_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') and v_mock->>'fresh_sampling'='true' and v_index>v_count
        and (v_run.session_id is null or v_id is distinct from v_run.plan->'itemIds'->>(v_index-1))
        and not exists(select 1 from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id and question_id=v_id and event_type='presented') then
        if v_prior is null then v_prior:=public.lp_literacy_exposures(v_student.id); end if;
        if jsonb_array_length(public.lp_literacy_familiarity_from_exposures(v_prior,v_item))>0 then
          return json_build_object('ok',false,'error','fresh_item_exposed'); end if;
      end if;
      if v_version in ('literacy-mock-v3','literacy-mock-v4') and v_mock->>'plan_kind'='fresh_check' then
        if not (v_mock->'candidate_item_ids' ? v_id) or public.lp_literacy_mock_conditions(v_item)<>v_mock->'focus' then
          return json_build_object('ok',false,'error','invalid_fresh_check_plan'); end if;
        if v_index>v_count and not exists(select 1 from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id and question_id=v_id and event_type='presented') then
          if v_prior is null then v_prior:=public.lp_literacy_exposures(v_student.id); end if;
          if jsonb_array_length(public.lp_literacy_familiarity_from_exposures(v_prior,v_item))>0 then
            return json_build_object('ok',false,'error','fresh_item_exposed'); end if;
        end if;
      end if;
      if v_version='literacy-mock-v4' and v_mock->>'plan_kind'='mixed'
      and coalesce((v_item#>>'{itemSnapshot,adaptiveMixedEligible}')::boolean,false)=false then
      return json_build_object('ok',false,'error','nonadaptive_mixed_task'); end if;
    if v_version in ('literacy-mock-v3','literacy-mock-v4') and v_run.session_id is null and v_mock->>'plan_kind'='mixed' and (v_item->>'level')::integer<>1 then
        return json_build_object('ok',false,'error','invalid_entry_level'); end if;
      if v_run.session_id is not null then
        select item into v_old_item from public.literacy_mock_items where id=v_run.plan->'itemIds'->>(v_index-1) and content_version=v_version;
        if (v_index<=v_count and to_jsonb(v_id)<>v_run.plan->'itemIds'->(v_index-1))
          or (v_version not in ('literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') and v_item->>'skillId' is distinct from v_old_item->>'skillId') or (v_version not in ('literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') and v_item->>'domainId' is distinct from v_old_item->>'domainId') then
          return json_build_object('ok',false,'error','plan_conflict'); end if;
        -- A content repair is the same task at the same level, including legacy sittings.
        if v_version not in ('literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') and public.lp_literacy_item_quarantined(v_old_item) and public.lp_literacy_mock_conditions(v_item) is distinct from public.lp_literacy_mock_conditions(v_old_item) then
          return json_build_object('ok',false,'error','plan_condition_conflict'); end if;
        if v_version in ('literacy-mock-v3','literacy-mock-v4') and public.lp_literacy_mock_conditions(v_item)-'level' is distinct from public.lp_literacy_mock_conditions(v_old_item)-'level' then
          return json_build_object('ok',false,'error','plan_condition_conflict'); end if;
        if v_version in ('literacy-mock-v3','literacy-mock-v4') and v_index>v_count and v_id<>v_run.plan->'itemIds'->>(v_index-1)
          and not public.lp_literacy_mock_item_blocked(v_old_item,v_run.media_failures)
          and not public.lp_literacy_item_quarantined(v_old_item)
          and exists(select 1 from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id
            and question_id=v_old_item->>'id' and event_type='presented') then
          return json_build_object('ok',false,'error','presented_item_frozen'); end if;
        if v_version not in ('literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') and v_index>v_count and v_id<>v_run.plan->'itemIds'->>(v_index-1) then
          select effective into v_previous from jsonb_array_elements(v_run.responses) with ordinality r(response,position)
            cross join lateral (select case when v_version in ('literacy-mock-v3','literacy-mock-v4')
              then public.lp_literacy_mock_effective_response(p_session_id,v_student.id,response) else response end effective) e
            where response->>'skillId'=v_item->>'skillId' and public.lp_literacy_response_eligible(effective)
              and (v_version not in ('literacy-mock-v3','literacy-mock-v4') or public.lp_literacy_mock_conditions(effective)-'level'=public.lp_literacy_mock_conditions(v_item)-'level')
            order by position desc limit 1;
          v_expected_level:=case when v_mock->>'plan_kind'='fresh_check' or public.lp_literacy_mock_item_blocked(v_old_item,v_run.media_failures)
            or public.lp_literacy_item_quarantined(v_old_item)
            then (v_old_item->>'level')::integer when v_previous is null then case when v_version in ('literacy-mock-v3','literacy-mock-v4') then 1 else (v_old_item->>'level')::integer end
            when (v_previous->>'isCorrect')::boolean then 2 else 1 end;
          if (v_item->>'level')::integer<>v_expected_level then return json_build_object('ok',false,'error','invalid_adaptation'); end if;
        end if;
      end if;
    end loop;
    -- A mixed mock must actually cover every advertised area. No claims are
    -- inferred from an area that a timer prevented the child from reaching.
    if coalesce(v_mock->>'plan_kind','mixed')='mixed' and (select count(distinct i.item->>'domainId') from jsonb_array_elements_text(p_plan->'itemIds') p(id)
      join public.literacy_mock_items i on i.id=p.id and i.content_version=v_version)<>8 then return json_build_object('ok',false,'error','incomplete_domain_plan'); end if;
    if v_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') and exists(select 1 from jsonb_array_elements_text(p_plan->'itemIds') p(id)
      join public.literacy_mock_items i on i.id=p.id and i.content_version=v_version
      group by coalesce(nullif(i.item#>>'{itemSnapshot,stimulusKey}',''),i.id) having count(*)>1) then
      return json_build_object('ok',false,'error','repeated_stimulus'); end if;
    if v_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') and v_mock->>'fresh_sampling'='true' and exists(
      select identity.key,identity.value from jsonb_array_elements_text(p_plan->'itemIds') with ordinality p(id,position)
        join public.literacy_mock_items i on i.id=p.id and i.content_version=v_version
        cross join lateral jsonb_each_text(public.lp_literacy_exposure_identity(i.item)) identity
      where nullif(identity.value,'') is not null group by identity.key,identity.value having count(*)>1 and (v_version in ('literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') or not bool_and(v_run.session_id is not null and coalesce(p.id=v_run.plan->'itemIds'->>(p.position::integer-1),false)))) then
      return json_build_object('ok',false,'error','repeated_exposure_identity'); end if;
    if v_version in ('literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') then
      v_area_error:=public.lp_mock_area_plan_error(p_session_id,v_student.id,p_plan,v_run.plan,v_count,v_run.media_failures);
      if v_area_error is not null then return json_build_object('ok',false,'error',v_area_error); end if;
    end if;
    v_plan:=p_plan;
  end if;
  if v_plan is null then return json_build_object('ok',false,'error','plan_required'); end if;
  if p_response is null and v_run.session_id is not null and v_plan=v_run.plan then
    return json_build_object('ok',true,'duplicate',true,'mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,v_student.id)); end if;
  if p_response is not null then
    if jsonb_typeof(p_response) is distinct from 'object'
      or exists(select 1 from jsonb_object_keys(p_response) k where k not in ('questionId','selected','responseStatus','audioDelivery','supportUsed','responseTimeMs','knownFamiliar','failedMediaPaths'))
      or p_response->>'questionId' is distinct from v_plan->'itemIds'->>v_count
      or p_response->>'responseStatus' is null or p_response->>'responseStatus' not in ('answered','skipped','media_failed')
      or jsonb_typeof(p_response->'audioDelivery') is distinct from 'object'
      or jsonb_typeof(p_response->'supportUsed') is distinct from 'boolean'
      or (p_response ? 'knownFamiliar' and jsonb_typeof(p_response->'knownFamiliar') not in ('null','boolean'))
      or (p_response ? 'responseTimeMs' and (jsonb_typeof(p_response->'responseTimeMs')<>'number'
        or (p_response->>'responseTimeMs')::numeric not between 0 and 7200000)) then
      return json_build_object('ok',false,'error','invalid_response'); end if;
    select item into v_item from public.literacy_mock_items where id=p_response->>'questionId' and content_version=v_version;
    if public.lp_literacy_item_quarantined(v_item) then return json_build_object('ok',false,'error','content_item_withdrawn'); end if;
    if v_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') then
      select payload into v_presentation from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id
        and question_id=p_response->>'questionId' and event_type='presented' order by event_id limit 1;
      if v_presentation is null then return json_build_object('ok',false,'error','presentation_required'); end if;
    end if;
    if p_response->>'responseStatus'<>'media_failed' and (p_response ? 'failedMediaPaths'
      or public.lp_literacy_mock_item_blocked(v_item,v_run.media_failures)) then
      return json_build_object('ok',false,'error','blocked_media_item'); end if;
    if p_response->>'responseStatus'='media_failed' then
      if v_run.session_id is null or (p_plan is not null and p_plan<>v_run.plan)
        or jsonb_typeof(p_response->'selected') is distinct from 'null'
        or jsonb_typeof(p_response->'failedMediaPaths') is distinct from 'array'
        or jsonb_array_length(p_response->'failedMediaPaths') not between 1 and 100
        or exists(select 1 from jsonb_array_elements(p_response->'failedMediaPaths') path where jsonb_typeof(path)<>'string')
        or exists(select 1 from jsonb_array_elements_text(p_response->'failedMediaPaths') failed where not exists(
          select 1 from jsonb_array_elements_text(public.lp_literacy_mock_media_paths(v_item)) required
          where split_part(failed,'#',1)=split_part(required,'#',1))) then
        return json_build_object('ok',false,'error','invalid_media_failure'); end if;
      -- Store exact canonical source paths, even when an image element reports
      -- a source URL without its atlas-cell fragment.
      select jsonb_agg(distinct required order by required) into v_failed_paths
        from jsonb_array_elements_text(public.lp_literacy_mock_media_paths(v_item)) required
        where exists(select 1 from jsonb_array_elements_text(p_response->'failedMediaPaths') failed
          where split_part(failed,'#',1)=split_part(required,'#',1));
    end if;
    if p_response->>'responseStatus'='answered' then
      if jsonb_typeof(p_response->'selected') not in ('string','array') or p_response->'selected' is null then
        return json_build_object('ok',false,'error','invalid_answer'); end if;
      if (v_item->>'answerMode' in ('set','sequence') and (jsonb_typeof(p_response->'selected')<>'array'
        or jsonb_array_length(p_response->'selected') not between 1 and 30
        or exists(select 1 from jsonb_array_elements(p_response->'selected') choice where jsonb_typeof(choice)<>'string')))
        or (v_item->>'answerMode' in ('exact','sentence') and jsonb_typeof(p_response->'selected')<>'string') then
        return json_build_object('ok',false,'error','invalid_answer'); end if;
      if v_item->>'answerMode'='set' and (select count(distinct value) from jsonb_array_elements(p_response->'selected'))<>jsonb_array_length(p_response->'selected') then
        return json_build_object('ok',false,'error','invalid_answer'); end if;
      if v_item->>'format' in ('choice','select_text','multi_select','order','match') and exists(
        select 1 from jsonb_array_elements_text(case when jsonb_typeof(p_response->'selected')='array'
          then p_response->'selected' else jsonb_build_array(p_response->'selected') end) chosen
        where not exists(select 1 from jsonb_array_elements(v_item->'choices') choice where choice->>'id'=chosen)) then
        return json_build_object('ok',false,'error','invalid_answer_choice'); end if;
      if exists(select 1 from jsonb_array_elements_text(v_item->'requiredAudioPaths') path where p_response->'audioDelivery'->>path is distinct from 'completed') then
        return json_build_object('ok',false,'error','audio_not_delivered'); end if;
    elsif coalesce(p_response->'selected','null'::jsonb)<>'null'::jsonb then
      return json_build_object('ok',false,'error','unscored_response_has_answer');
    end if;
    if exists(select 1 from jsonb_each(p_response->'audioDelivery') cue
      where not (v_item->'requiredAudioPaths' ? cue.key) or cue.value not in ('"completed"'::jsonb,'"failed"'::jsonb)) then
      return json_build_object('ok',false,'error','invalid_audio_receipt'); end if;
    v_now:=clock_timestamp();
    -- Recheck after validation, so a slow transaction cannot submit on an old clock.
    if (v_mock->>'deadline_at')::timestamptz<=v_now then
      v_mock:=public.lp_literacy_mock_state(p_session_id);
      return json_build_object('ok',false,'error','assessment_finished','mock',v_mock); end if;
    v_valid:=p_response->>'responseStatus'='answered' and not (p_response->>'supportUsed')::boolean;
    v_familiarity:=case when v_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') then v_presentation->'familiarityReasons' else public.lp_literacy_familiarity(v_student.id,v_item) end;
    v_answer:=p_response||public.lp_literacy_exposure_identity(v_item)||jsonb_build_object('questionId',v_item->>'id','skillId',v_item->>'skillId',
      'domainId',v_item->>'domainId','level',v_item->'level','itemSnapshot',v_item->'itemSnapshot',
      'isCorrect',case when p_response->>'responseStatus'='answered' then public.lp_literacy_mock_normalize_answer(p_response->'selected',v_item->>'answerMode')
        =public.lp_literacy_mock_normalize_answer(v_item->'answer',v_item->>'answerMode') else null end,
      'evidenceType',case when v_valid then 'independent' when p_response->>'responseStatus'='answered' then 'supported' else 'unscored' end,
      'presentationRole','first_probe','administration','rehearsal','presentationVersion','mock-explicit-submit-v1',
      'familiarityReasons',v_familiarity,'knownFamiliar',case when jsonb_array_length(v_familiarity)>0
        then 'true'::jsonb else coalesce(p_response->'knownFamiliar','null'::jsonb) end,'serverReceivedAt',v_now,'occurredAt',v_now);
    if v_version in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') then v_answer:=public.lp_literacy_mock_effective_response(p_session_id,v_student.id,v_answer); end if;
    if p_response->>'responseStatus'='media_failed' then
      v_failure:=v_answer||jsonb_build_object('failedMediaPaths',v_failed_paths);
      v_answer:=null;
    end if;
  end if;
  if v_run.session_id is null then
    insert into public.literacy_mock_runs(session_id,student_id,plan) values(p_session_id,v_student.id,v_plan) returning * into v_run;
  end if;
  update public.literacy_mock_runs set plan=v_plan,revision=revision+1,
    responses=responses||case when v_answer is null then '[]'::jsonb else jsonb_build_array(v_answer) end,
    media_failures=media_failures||case when v_failure is null then '[]'::jsonb else jsonb_build_array(v_failure) end,
    status=case when v_failure is not null then status when v_count+case when v_answer is null then 0 else 1 end=jsonb_array_length(v_plan->'itemIds') then 'completed'
      when v_mock->>'state'='prepared' then 'ready' else 'running' end,
    completed_at=case when v_count+case when v_answer is null then 0 else 1 end=jsonb_array_length(v_plan->'itemIds') then clock_timestamp() else null end,
    updated_at=clock_timestamp() where session_id=p_session_id and student_id=v_student.id returning * into v_run;
  insert into public.literacy_mock_run_requests(session_id,student_id,request_id,request_payload,result_revision)
    values(p_session_id,v_student.id,p_request_id,v_payload,v_run.revision);
  if v_run.status='completed' then update public.student_focus_session_members set status='completed',completed_at=v_run.completed_at,updated_at=clock_timestamp()
    where session_id=p_session_id and student_id=v_student.id; end if;
  return json_build_object('ok',true,'mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,v_student.id));
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then
  return json_build_object('ok',false,'error','invalid_payload');
end; $$;

create or replace function public.student_record_literacy_mock_event(p_token text,p_session_id uuid,p_question_id text,p_event text,p_request_id text)
returns json language plpgsql volatile security definer set search_path='' as $$
declare v_student public.students; v_mock jsonb; v_run public.literacy_mock_runs; v_event public.literacy_mock_events;
 v_item jsonb; v_payload jsonb; v_familiarity jsonb; v_rows jsonb; v_states jsonb;
begin
 v_student:=public.student_from_token(p_token);
 if v_student.id is null then return json_build_object('ok',false,'error','invalid_session'); end if;
 perform 1 from public.students where id=v_student.id for share;
 if not public.lp_literacy_mock_assignment(v_student.id,p_session_id) then return json_build_object('ok',false,'error','assignment_not_found'); end if;
 if p_event is null or p_event not in ('presented','help_requested','help_cancelled') or coalesce(char_length(p_question_id),0) not between 1 and 240
  or coalesce(char_length(p_request_id),0) not between 1 and 160 then return json_build_object('ok',false,'error','invalid_event'); end if;
 v_mock:=public.lp_literacy_mock_state(p_session_id);
 if v_mock->>'content_version' not in ('literacy-mock-v3','literacy-mock-v4','literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8','literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') then return json_build_object('ok',false,'error','unsupported_event_version'); end if;
 select * into v_run from public.literacy_mock_runs where session_id=p_session_id and student_id=v_student.id for update;
 if not found then return json_build_object('ok',false,'error','plan_required'); end if;
 select * into v_event from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id and actor_key='student' and request_id=p_request_id;
 if found then
  if v_event.event_type<>p_event or v_event.question_id<>p_question_id then return json_build_object('ok',false,'error','request_conflict'); end if;
  return json_build_object('ok',true,'duplicate',true,'mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,v_student.id));
 end if;
 -- Repeated render callbacks are a single offer, not additional familiarity.
 if p_event='presented' and exists(select 1 from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id and question_id=p_question_id and event_type='presented') then
  return json_build_object('ok',true,'duplicate',true,'mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,v_student.id)); end if;
 if v_mock->>'state'<>'running' or v_run.status='completed' then return json_build_object('ok',false,'error','assessment_not_running','mock',v_mock); end if;
 if p_question_id is distinct from v_run.plan->'itemIds'->>jsonb_array_length(v_run.responses) then return json_build_object('ok',false,'error','question_not_current'); end if;
 if not exists(select 1 from public.student_focus_session_members where session_id=p_session_id and student_id=v_student.id and active) then
  return json_build_object('ok',false,'error','assignment_not_found'); end if;
 select item into v_item from public.literacy_mock_items where content_version=v_mock->>'content_version' and id=p_question_id;
 if public.lp_literacy_item_quarantined(v_item) then return json_build_object('ok',false,'error','content_item_withdrawn'); end if;
 if v_item is null or public.lp_literacy_mock_item_blocked(v_item,v_run.media_failures) then return json_build_object('ok',false,'error','blocked_media_item'); end if;
 if v_mock->>'content_version' in ('literacy-mock-v9','literacy-mock-v10','literacy-mock-v11') and p_event='presented' then
  -- One current canonical/support projection serves all three guards. No
  -- projection survives this request; later assistance is read again.
  v_rows:=public.lp_mock_boundary_rows_v9(p_session_id,v_student.id);
  v_states:=public.lp_mock_boundary_state_for_version(v_rows,v_mock->>'content_version');
  if (v_states#>>array[v_item->>'domainId','complete'])::boolean
   or public.lp_mock_boundary_schedule_for_version(v_rows,v_states,v_mock->>'content_version')->>jsonb_array_length(v_run.responses) is distinct from v_item->>'domainId'
   or public.lp_mock_area_band(v_item) is distinct from (v_states#>>array[v_item->>'domainId','nextBand'])::integer then
   return json_build_object('ok',false,'error','invalid_adaptation'); end if;
 elsif v_mock->>'content_version' in ('literacy-mock-v5','literacy-mock-v6','literacy-mock-v7','literacy-mock-v8') and p_event='presented'
  and public.lp_mock_area_band(v_item) is distinct from public.lp_mock_area_next_band(p_session_id,v_student.id,v_item->>'domainId') then
  return json_build_object('ok',false,'error','invalid_adaptation'); end if;
 if p_event in ('help_requested','help_cancelled') and not exists(select 1 from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id and question_id=p_question_id and event_type='presented') then
  return json_build_object('ok',false,'error','presentation_required'); end if;
 if p_event='help_cancelled' and public.lp_literacy_mock_help(p_session_id,v_student.id,p_question_id)->>'pending'<>'true' then
  return json_build_object('ok',false,'error','help_not_pending'); end if;
 if (select count(*) from public.literacy_mock_events where session_id=p_session_id and student_id=v_student.id)>=512 then
  return json_build_object('ok',false,'error','event_limit'); end if;
 v_familiarity:=public.lp_literacy_familiarity(v_student.id,v_item);
 v_payload:=public.lp_literacy_exposure_identity(v_item)||jsonb_build_object('questionId',p_question_id,
  'skillId',v_item->>'skillId','domainId',v_item->>'domainId','level',v_item->'level','itemSnapshot',v_item->'itemSnapshot',
  'presentationStatus','presented','knownFamiliar',case when jsonb_array_length(v_familiarity)>0 then 'true'::jsonb else 'null'::jsonb end,
  'familiarityReasons',v_familiarity);
 insert into public.literacy_mock_events(session_id,student_id,question_id,actor_key,request_id,event_type,payload)
  values(p_session_id,v_student.id,p_question_id,'student',p_request_id,p_event,case when p_event='presented' then v_payload else '{}'::jsonb end);
 return json_build_object('ok',true,'mock',v_mock,'run',public.lp_literacy_mock_run_json(p_session_id,v_student.id));
end; $$;

create or replace function public.lp_mock_area_next_band(p_session_id uuid,p_student_id uuid,p_domain text)
returns integer language plpgsql stable security definer set search_path='' as $$
begin
 if exists(select 1 from public.student_focus_sessions where id=p_session_id and content_version in ('literacy-mock-v9','literacy-mock-v10','literacy-mock-v11')) then
  return (public.lp_mock_boundary_state_for_version(public.lp_mock_boundary_rows_v9(p_session_id,p_student_id),(select content_version from public.student_focus_sessions where id=p_session_id))#>>array[p_domain,'nextBand'])::integer;
 end if;
 return public.lp_mock_area_next_band_before_v9(p_session_id,p_student_id,p_domain);
end; $$;

create or replace function public.lp_mock_area_plan_error(p_session_id uuid,p_student_id uuid,p_plan jsonb,p_old_plan jsonb,p_answered integer,p_failures jsonb)
returns text language plpgsql stable security definer set search_path='' as $$
begin
 if exists(select 1 from public.student_focus_sessions where id=p_session_id and content_version in ('literacy-mock-v9','literacy-mock-v10','literacy-mock-v11')) then
  return public.lp_mock_boundary_plan_error_v9(p_session_id,p_student_id,p_plan,p_old_plan,p_answered,p_failures);
 end if;
 return public.lp_mock_area_plan_error_before_v9(p_session_id,p_student_id,p_plan,p_old_plan,p_answered,p_failures);
end; $$;

create or replace function public.lp_mock_boundary_rows_v9(p_session_id uuid,p_student_id uuid)
returns jsonb language sql stable security definer set search_path='' as $$
 -- Support is current at this statement, including late teacher resolutions.
 -- One grouped event read replaces a help query for every historical answer.
 with support as materialized (
  select question_id,max(event_id) filter(where event_type='help_requested') requested,
   max(event_id) filter(where event_type='help_cancelled') cancelled,
   max(event_id) filter(where event_type='support_resolved') resolved,
   bool_or(payload->>'assistance'='answer') filter(where event_type='support_resolved') answer_help,
   bool_or(payload->>'assistance'='access') filter(where event_type='support_resolved') access_help
  from public.literacy_mock_events where session_id=p_session_id and student_id=p_student_id
   and event_type in ('help_requested','help_cancelled','support_resolved') group by question_id
 )
 select coalesce(jsonb_agg(public.lp_mock_response_with_help_v9(r.response,jsonb_build_object(
   'helpRequested',s.requested is not null,
   'pending',coalesce(s.requested>greatest(coalesce(s.resolved,0),coalesce(s.cancelled,0)),false),
   'assistanceType',case when s.answer_help then 'answer' when s.access_help then 'access' else 'none' end))
   ||jsonb_build_object('questionId',i.id,'domainId',i.item->'domainId','skillId',i.item->'skillId','itemSnapshot',i.item->'itemSnapshot') order by r.position),'[]'::jsonb)
 from public.literacy_mock_runs run join public.student_focus_sessions boundary_focus on boundary_focus.id=run.session_id cross join lateral jsonb_array_elements(run.responses) with ordinality r(response,position)
 join public.literacy_mock_items i on i.content_version=boundary_focus.content_version and i.id=r.response->>'questionId'
 left join support s on s.question_id=r.response->>'questionId'
 where run.session_id=p_session_id and run.student_id=p_student_id;
$$;

create or replace function public.lp_mock_boundary_plan_error_v9(p_session_id uuid,p_student_id uuid,p_plan jsonb,p_old_plan jsonb,p_answered integer,p_failures jsonb)
returns text language plpgsql stable security definer set search_path='' as $$
declare v_version text:=(select content_version from public.student_focus_sessions where id=p_session_id); v_rows jsonb:=public.lp_mock_boundary_rows_v9(p_session_id,p_student_id); v_reserved jsonb; v_states jsonb; v_schedule jsonb;
 v_id text; v_index integer; v_item jsonb; v_old jsonb; v_current jsonb; v_domain text; v_band integer; v_expected integer;
 v_ordinals jsonb:='{}'; v_first jsonb:='{}'; v_ordinal integer; v_shown boolean:=false; v_repair boolean:=false;
begin
 if p_answered<>jsonb_array_length(v_rows) or jsonb_typeof(p_plan->'itemIds') is distinct from 'array'
  or jsonb_array_length(p_plan->'itemIds') not between p_answered and (case when v_version='literacy-mock-v11' then 124 else 67 end) then return 'invalid_plan'; end if;
 v_states:=public.lp_mock_boundary_state_for_version(v_rows,v_version); v_reserved:=v_rows;
 if p_old_plan is not null then
  select item into v_current from public.literacy_mock_items where content_version=v_version and id=p_old_plan->'itemIds'->>p_answered;
  v_shown:=v_current is not null and exists(select 1 from public.literacy_mock_events where session_id=p_session_id and student_id=p_student_id and question_id=v_current->>'id' and event_type='presented');
  if v_current is not null and (v_shown or public.lp_literacy_mock_item_blocked(v_current,p_failures)) then
   v_reserved:=v_rows||jsonb_build_array(jsonb_build_object('questionId',v_current->'id','itemSnapshot',v_current->'itemSnapshot','responseStatus','skipped','evidenceType','unscored','isCorrect',null));
  end if;
  -- Media/content repair is a separate transition, preserving every other
  -- slot and the exact failed task before ordinary adaptation resumes.
  if jsonb_array_length(p_plan->'itemIds')=jsonb_array_length(p_old_plan->'itemIds') and p_plan->'itemIds' is distinct from p_old_plan->'itemIds' then
   v_repair:=true;
   for v_id,v_index in select value,ordinality::integer from jsonb_array_elements_text(p_plan->'itemIds') with ordinality loop
    if v_id=p_old_plan->'itemIds'->>(v_index-1) then continue; end if;
    select item into v_old from public.literacy_mock_items where content_version=v_version and id=p_old_plan->'itemIds'->>(v_index-1);
    select item into v_item from public.literacy_mock_items where content_version=v_version and id=v_id;
    if v_index<=p_answered or v_item is null or not (public.lp_literacy_mock_item_blocked(v_old,p_failures) or public.lp_literacy_item_quarantined(v_old))
     or public.lp_literacy_mock_conditions(v_item) is distinct from public.lp_literacy_mock_conditions(v_old)
     or public.lp_mock_area_band(v_item) is distinct from public.lp_mock_area_band(v_old)
     or public.lp_literacy_item_quarantined(v_item) or public.lp_literacy_mock_item_blocked(v_item,p_failures)
     or v_item#>>'{itemSnapshot,adaptiveMixedEligible}' is distinct from 'true' then v_repair:=false; exit; end if;
   end loop;
   if v_repair then return null; end if;
  end if;
 end if;
 v_schedule:=public.lp_mock_boundary_schedule_for_version(v_reserved,
  case when v_reserved=v_rows then v_states else public.lp_mock_boundary_state_for_version(v_reserved,v_version) end,v_version);
 if jsonb_array_length(p_plan->'itemIds')<>jsonb_array_length(v_schedule) then return 'invalid_plan'; end if;
 for v_id,v_index in select value,ordinality::integer from jsonb_array_elements_text(p_plan->'itemIds') with ordinality loop
  select item into v_item from public.literacy_mock_items where content_version=v_version and id=v_id;
  v_domain:=v_schedule->>(v_index-1); v_band:=public.lp_mock_area_band(v_item);
  if v_item is null or v_item->>'domainId' is distinct from v_domain or v_band is null
   or v_item#>>'{itemSnapshot,adaptiveAreaVersion}' is distinct from (case when v_version='literacy-mock-v11' then 'areas-v6' else 'areas-v5' end)
   or v_item#>>'{itemSnapshot,adaptiveMixedEligible}' is distinct from 'true' then return 'invalid_area_plan'; end if;
  v_ordinal:=coalesce((v_ordinals->>v_domain)::integer,0)+1; v_ordinals:=v_ordinals||jsonb_build_object(v_domain,v_ordinal);
  if v_index<=p_answered then
   if v_id is distinct from v_rows->(v_index-1)->>'questionId' then return 'plan_conflict'; end if;
   continue;
  end if;
  if not v_first ? v_domain then
   v_first:=v_first||jsonb_build_object(v_domain,true); v_expected:=(v_states#>>array[v_domain,'nextBand'])::integer;
  else v_expected:=case when v_version='literacy-mock-v11' then public.lp_mock_placeholder_band_v11(v_domain,v_ordinal) else case when v_domain='print' and v_ordinal>5 then 2 else 0 end end;
  end if;
  if v_index=p_answered+1 and jsonb_array_length(v_reserved)>p_answered then
   if v_id is distinct from v_current->>'id' then return 'presented_item_frozen'; end if;
   v_expected:=public.lp_mock_area_band(v_current);
  end if;
  if v_band is distinct from v_expected then return case when p_old_plan is null then 'invalid_entry_level' else 'invalid_adaptation' end; end if;
 end loop;
 return null;
end; $$;

create or replace function public.lp_mock_prepare_v11_before_delivery(p_class_id uuid,p_student_ids uuid[] default '{}',
  p_whole_class boolean default false,p_duration_minutes integer default 20,p_item_count integer default 124,p_request_id text default null,p_window_mode text default 'pause_at_window_end')
returns json language plpgsql volatile security definer set search_path='' as $$
declare v_result jsonb; v_id uuid; v_saved public.literacy_mock_preparations; v_hash text; v_version text:='literacy-mock-v11';
begin
  perform public.assert_current_actor_teacher_access();
  if p_window_mode is null or p_window_mode not in ('pause_at_window_end','timed_sample') or p_duration_minutes is null or p_duration_minutes not in (10,20,30,40)
    or p_item_count is null or p_item_count<>124 then
    return json_build_object('ok',false,'error','invalid_mock_options'); end if;
  if p_request_id is not null and char_length(p_request_id) not between 1 and 160 then
    return json_build_object('ok',false,'error','invalid_request_id'); end if;
  if p_request_id is not null then
    perform pg_advisory_xact_lock(hashtextextended('literacy-mock-prepare:'||auth.uid()::text,0));
    -- The fingerprint contains no recoverable pupil identifiers after deletion.
    v_hash:=encode(sha256(convert_to(jsonb_build_object('classId',p_class_id,'studentIds',p_student_ids,
      'wholeClass',p_whole_class,'minutes',p_duration_minutes,'count',p_item_count,'windowMode',p_window_mode,'version',v_version)::text,'UTF8')),'hex');
    select * into v_saved from public.literacy_mock_preparations where teacher_id=auth.uid() and request_id=p_request_id;
    if found then
      if v_saved.payload_hash<>v_hash then return json_build_object('ok',false,'error','request_conflict'); end if;
      return (public.teacher_get_student_focus_session(v_saved.session_id)::jsonb||jsonb_build_object('duplicate',true))::json;
    end if;
  end if;
  if not exists(select 1 from public.literacy_mock_publications p where p.content_version=v_version and p.available_for_new_sessions
      and p.item_count=(select count(*) from public.literacy_mock_items i where i.content_version=p.content_version)
      and (select count(distinct item->>'domainId') from public.literacy_mock_items i where i.content_version=p.content_version)=8) then
    return json_build_object('ok',false,'error','mock_v11_unavailable'); end if;
  v_result:=public.lp_prepare_literacy_mock_focus(p_class_id,p_student_ids,p_whole_class,v_version);
  if v_result->>'ok'<>'true' then return v_result::json; end if;
  v_id:=(v_result#>>'{session,id}')::uuid;
  insert into public.literacy_mock_sessions(session_id,item_count,duration_seconds,remaining_seconds,window_mode,fresh_sampling)
    values(v_id,p_item_count,p_duration_minutes*60,p_duration_minutes*60,p_window_mode,true);
  if p_request_id is not null then insert into public.literacy_mock_preparations(teacher_id,request_id,payload_hash,session_id)
    values(auth.uid(),p_request_id,v_hash,v_id); end if;
  return public.teacher_get_student_focus_session(v_id);
end; $$;

create or replace function public.teacher_prepare_literacy_mock_session_v11(p_class_id uuid,p_student_ids uuid[] default '{}',
 p_whole_class boolean default false,p_duration_minutes integer default 20,p_item_count integer default 124,p_request_id text default null,p_window_mode text default 'untimed')
returns json language plpgsql volatile security definer set search_path='' as $$
declare v_result jsonb;
begin
 if p_window_mode not in ('timed_sample','pause_at_window_end','untimed') then return json_build_object('ok',false,'error','invalid_window_mode'); end if;
 v_result:=public.lp_mock_prepare_v11_before_delivery(p_class_id,p_student_ids,p_whole_class,p_duration_minutes,p_item_count,p_request_id,
  case when p_window_mode='untimed' then 'pause_at_window_end' else p_window_mode end)::jsonb;
 if v_result->>'ok'='true' and coalesce((v_result->>'duplicate')::boolean,false)=false then
  update public.literacy_mock_sessions set delivery_mode=case when p_window_mode='untimed' then 'collect' else 'live' end,
   window_mode=p_window_mode where session_id=(v_result#>>'{session,id}')::uuid;
  return public.teacher_get_student_focus_session((v_result#>>'{session,id}')::uuid);
 end if;
 if v_result->>'ok'='true' and v_result#>>'{session,mock,window_mode}' is distinct from p_window_mode then
  return json_build_object('ok',false,'error','request_conflict'); end if;
 return v_result::json;
end; $$;

